use regex::Regex;

pub struct Entry {
    pub level: String,
    pub message: String,
}

pub fn parse_lines(lines: &[&str]) -> Vec<Entry> {
    let mut entries = Vec::new();
    for line in lines {
        let re = Regex::new(r"^\[(\w+)\] (.+)$").unwrap();
        if let Some(caps) = re.captures(line) {
            entries.push(Entry {
                level: caps[1].to_string(),
                message: caps[2].to_string(),
            });
        }
    }
    entries
}

