use std::sync::LazyLock;

use regex::Regex;

static LINE: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"^\[(\w+)\] (.+)$").unwrap());

pub struct Entry {
    pub level: String,
    pub message: String,
}

pub fn parse_lines(lines: &[&str]) -> Vec<Entry> {
    lines
        .iter()
        .filter_map(|line| LINE.captures(line))
        .map(|caps| Entry {
            level: caps[1].to_string(),
            message: caps[2].to_string(),
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn line_pattern_compiles() {
        LazyLock::force(&LINE);
    }
}
